#include "club/Club.h"
#include "cards/CardCatalog.h"
#include "networking/NetworkRoom.h"
#include <numeric>
#include <iostream>
#include <thread>
#include <chrono>
using namespace fl;using namespace fl::net;
void check(bool b,const char* s){if(!b)throw std::runtime_error(s);}unsigned count(const ClubProfile&p){return std::accumulate(p.owned.begin(),p.owned.end(),0U);}ClubCommand cmd(ClubOp op){ClubCommand c;c.op=op;c.request=newRequestId();return c;}
int main(){try{auto defs=unlimitedDefinitions();auto path=std::filesystem::temp_directory_path()/(newRequestId()+".sqlite3");ClubCommand purchase=cmd(ClubOp::Pack);std::vector<std::uint16_t> out;{ClubStore store(path,defs);store.ensure("new",0);check(count(store.profile("new"))==0&&store.profile("new").decks.empty(),"Free starter cards remain");auto land=cmd(ClubOp::Land);for(int i=0;i<302;++i)if(defs[i].basicLand){land.value=i;break;}store.apply("new",land,out);check(store.profile("new").cents==49900&&count(store.profile("new"))==1,"Land must cost 1 dollar");store.apply("new",purchase,out);check(count(store.profile("new"))==16&&out.size()==15,"Pack count");store.apply("new",purchase,out);check(count(store.profile("new"))==16,"Duplicate pack");} {ClubStore store(path,defs);store.ensure("new",0);check(count(store.profile("new"))==16,"Existing profile was reset");store.apply("new",purchase,out);check(count(store.profile("new"))==16,"Restart replay");}std::filesystem::remove(path);
NetworkRoom h,g;unsigned short port=35845;while(port<35865&&!h.host(port))++port;check(port<35865&&g.join("127.0.0.1",port),"Connect failed");auto pump=[&](int n){while(n--){h.update(.01F);g.update(.01F);std::this_thread::sleep_for(std::chrono::milliseconds(1));}};pump(150);Tabletop a,b;h.syncTable(a);g.syncTable(b);check(a.cards().empty()&&b.cards().empty(),"Free demo table remains");check(count(g.club().profile)==0,"Guest starts with cards");h.clubCommand(cmd(ClubOp::Pack));g.clubCommand(cmd(ClubOp::Pack));pump(50);for(auto* peer:{&h,&g}){auto save=cmd(ClubOp::SaveDeck);save.name="First";for(int i=0;i<302;++i)for(unsigned n=0;n<peer->club().profile.owned[i];++n)save.cards.push_back(static_cast<std::uint16_t>(i));peer->clubCommand(save);}pump(40);for(auto* peer:{&h,&g}){auto select=cmd(ClubOp::SelectDeck);select.name="First";peer->clubCommand(select);}pump(40);h.clubCommand(cmd(ClubOp::Ready));g.clubCommand(cmd(ClubOp::Ready));pump(50);h.syncTable(a);g.syncTable(b);check(a.cards().size()==30&&b.hand(1).size()==7,"Purchased decks failed");h.stop();g.stop();std::cout<<"PASS: zero-card new profiles/room, $1 lands, purchases, restart/replay, existing saves retained, empty snapshots, UDP purchased-deck setup\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
